sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	if (current.from_date && current.to_date) {
    if (current.to_date < current.from_date) {
        gs.addErrorMessage("End date must be after or equal to start date");
        action.setAbortAction(true);
    }
}

})(current, previous);
